result:
Confirma que la fuente usa `require` sólo por decisión de estilo (lazy require), y `getSandboxBinaryPath` real vive en `settings.ts` de la fuente pero no está portado a thyrox. Con eso completo la propuesta.

```json
{"file": "src/packages/shell/src/sandbox/sandbox-adapter.ts",
 "edits": [{"old": "      try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const { getSandboxBinaryPath } = require(
          '@thyrox/config/settings',
        ) as typeof import('@thyrox/config/settings')
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const path = require('node:path') as typeof import('node:path')
        const extraDirs: string[] = []
        for (const field of ['bwrapPath', 'socatPath'] as const) {
          const p = getSandboxBinaryPath(field)
          if (p && p.length > 0) extraDirs.push(path.dirname(p))
        }
        if (extraDirs.length > 0) {
          const existing = process.env.PATH ?? ''
          const sep = process.platform === 'win32' ? ';' : ':'
          process.env.PATH = [...extraDirs, existing].filter(Boolean).join(sep)
        }
      } catch (e) {
        logForDebugging(`Failed to read sandbox.bwrapPath/socatPath: ${errorMessage(e)}`)
      }",
           "new": "      try {
        // `getSandboxBinaryPath` (fuente: settings.ts) no está portado a
        // @thyrox/config/settings — se inlinea aquí el mismo recorrido en
        // capas (primer valor no vacío gana, de mayor a menor precedencia)
        // con lo que este archivo ya importa.
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const path = require('node:path') as typeof import('node:path')
        const extraDirs: string[] = []
        for (const field of ['bwrapPath', 'socatPath'] as const) {
          let p: string | undefined
          for (const source of [...SETTING_SOURCES].reverse()) {
            const candidate = getSettingsForSource(source)?.sandbox?.[field]
            if (candidate != null && candidate.length > 0) {
              p = candidate
              break
            }
          }
          if (p && p.length > 0) extraDirs.push(path.dirname(p))
        }
        if (extraDirs.length > 0) {
          const existing = process.env.PATH ?? ''
          const sep = process.platform === 'win32' ? ';' : ':'
          process.env.PATH = [...extraDirs, existing].filter(Boolean).join(sep)
        }
      } catch (e) {
        logForDebugging(`Failed to read sandbox.bwrapPath/socatPath: ${errorMessage(e)}`)
      }"}],
